import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class Main {

    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    static String readLn() { // string line
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static int readInt() { // single int
        return Integer.parseInt(readLn());
    }

    static List<String> readStrings() { // list of strings
        return Arrays.asList(readLn().split(" "));
    }

    static List<Integer> readInts() { // list of ints
        return readStrings().stream().map(Integer::parseInt).collect(Collectors.toList());
    }

    static int findLissPos() {

        String stones = readLn();
        String instructions = readLn();
        int curPos = 0;
        for (int i = 0; i < instructions.length(); i++) {
            if (stones.charAt(curPos) == instructions.charAt(i))
                curPos++;
        }

        curPos++;

        return curPos;
    }

    public static void main(String[] args) {
        System.out.print(findLissPos());
    }
}
